"""Inspect actual PDFs generated by layout.test.mjs, including Unicode extraction."""
import json
import re
import sys
import unicodedata
from pathlib import Path
import pypdf
import pypdfium2 as pdfium

root = Path(__file__).resolve().parents[2] / 'validation'
browser = json.loads((root / 'browser-results.json').read_text())
results = []
strict_failures = []
for item in browser['results']:
    name = item['case']
    reader = pypdf.PdfReader(root / f'{name}.pdf')
    assert len(reader.pages) == item['pages'], (name, len(reader.pages), item['pages'])
    landscape = name == 'landscape'
    expected = (841.89, 595.28) if landscape else (595.28, 841.89)
    for page in reader.pages:
        assert abs(float(page.mediabox.width) - expected[0]) < 1
        assert abs(float(page.mediabox.height) - expected[1]) < 1
    text = '\n'.join(p.extract_text() or '' for p in reader.pages)
    checks = {}
    if name != 'empty':
        for word in ['हिंदी', 'क्षत्रिय', 'विद्यालय', 'श्रद्धा', 'प्रार्थना']:
            checks[word] = word in text
        if not all(checks.values()):
            strict_failures.append(name)
    (root / f'{name}-extracted.txt').write_text(text, encoding='utf-8')
    pdf = pdfium.PdfDocument(root / f'{name}.pdf')
    pdfium_text = '\n'.join(pdf[i].get_textpage().get_text_range() for i in range(len(pdf)))
    normalized = re.sub(r'\s+', '', unicodedata.normalize('NFC',pdfium_text))
    pdfium_checks = {word:word in normalized for word in checks}
    (root / f'{name}-pdfium.txt').write_text(pdfium_text,encoding='utf-8')
    indices = sorted(set([0, len(pdf)//2, len(pdf)-1]))
    for index in indices:
        image = pdf[index].render(scale=1.25).to_pil()
        image.save(root / f'{name}-page-{index+1}.png')
    results.append({'case':name, 'pdfPages':len(reader.pages), 'previewMatch':True, 'a4':True, 'pypdfExactExtraction':checks, 'pdfiumWhitespaceNormalizedWords':pdfium_checks})
    print(name, len(reader.pages), 'pages; A4 / preview match passed;', 'exact extraction FAILED' if name in strict_failures else 'extraction passed')
(root / 'pdf-results.json').write_text(json.dumps(results,ensure_ascii=False,indent=2),encoding='utf-8')
if strict_failures:
    print('Strict Hindi extraction failures (not waived):', ', '.join(strict_failures))
    sys.exit(1)
